import {Chess} from './vendor/chess.js';
import {Engine,TYPES,classify,terminal} from './analysis.js';
const $=id=>document.getElementById(id),names={p:'pedone',n:'cavallo',b:'alfiere',r:'torre',q:'donna',k:'re'},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let game=null,positions=[new Chess().fen()],moves=[],results=[],grades=[],headers={},index=0,flipped=false,selected=null,exploring=false,branches=[],activeBranch=null,branchIndex=0,busy=false,runId=0,liveId=0,liveResult=null,openingMap={},bookReady=false;
const engine=new Engine(s=>{$('engineStatus').textContent=s;});
fetch('vendor/openings.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{openingMap=d;bookReady=true}).catch(()=>notify('Il database delle aperture non è disponibile: la categoria Teoria sarà omessa.'));
const quality=()=>$('quality').value;
const fenKey=fen=>fen.split(' ').slice(0,4).join(' ');
const currentFen=()=>activeBranch?activeBranch.positions[branchIndex]:positions[index];
const currentChess=()=>new Chess(currentFen());
const currentResult=()=>activeBranch?activeBranch.results[branchIndex]:results[index];
const labelScore=r=>!r?'—':r.mate!==null&&r.mate!==undefined?`${r.cp<0?'−':''}M${Math.abs(r.mate)}`:(r.cp/100>0?'+':'')+(r.cp/100).toFixed(2);
function notify(t){$('message').hidden=!t;$('message').textContent=t}
function badge(type){let t=TYPES[type];return t?`<span class="badge" style="--badge:${t.color}" title="${t.label}" aria-label="${t.label}">${t.icon}</span>`:''}
function renderBoard(){const chess=currentChess(),legal=selected?chess.moves({square:selected,verbose:true}).map(m=>m.to):[];let prev=activeBranch?(branchIndex?activeBranch.moves[branchIndex-1]:moves[activeBranch.base-1]):moves[index-1];let html='';for(let row=0;row<8;row++)for(let col=0;col<8;col++){let f=flipped?7-col:col,r=flipped?row:7-row,sq='abcdefgh'[f]+(r+1),p=chess.get(sq);html+=`<button class="square ${(f+r)%2===0?'dark':''} ${sq===selected?'selected':''} ${legal.includes(sq)?'legal':''} ${prev&&(prev.from===sq||prev.to===sq)?'last':''}" data-sq="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'Bianco ':'Nero ')+names[p.type]:''}" ${busy?'disabled':''}>${p?`<img src="pieces/${p.color}${p.type.toUpperCase()}.png" alt="" draggable="false">`:''}${col===0?`<span class="coord rank">${r+1}</span>`:''}${row===7?`<span class="coord">${'abcdefgh'[f]}</span>`:''}</button>`}$('board').innerHTML=html;let r=currentResult();$('evalNumber').textContent=labelScore(r);$('evalWhite').style.height=(r?Math.max(3,Math.min(97,50+45*Math.tanh(r.cp/450))):50)+'%';$('positionLabel').textContent=activeBranch?`Variante · ${branchIndex}/${activeBranch.moves.length}`:`${index===0?'Posizione iniziale':`Mossa ${new Chess(moves[index-1].before).moveNumber()}${moves[index-1].color==='w'?' · Bianco':' · Nero'}`}`;let n=activeBranch?branchIndex:index,total=activeBranch?activeBranch.moves.length:moves.length;['first','prev'].forEach(k=>$(k).disabled=n===0);['last','next'].forEach(k=>$(k).disabled=n===total);$('topName').textContent=flipped?(headers.White||'Bianco'):(headers.Black||'Nero');$('bottomName').textContent=flipped?(headers.Black||'Nero'):(headers.White||'Bianco');$('topRating').textContent=(flipped?headers.WhiteElo:headers.BlackElo)||' ';$('bottomRating').textContent=(flipped?headers.BlackElo:headers.WhiteElo)||' ';$('topAcc').textContent=flipped?$('whiteAccuracy').textContent:$('blackAccuracy').textContent;$('bottomAcc').textContent=flipped?$('blackAccuracy').textContent:$('whiteAccuracy').textContent;$('boardHint').textContent=busy?'Stockfish sta analizzando. Puoi già leggere le mosse completate.':activeBranch?'Variante attiva · muovi entrambi i colori sulla scacchiera.':game?'Seleziona una mossa. In Esplora puoi provare altre continuazioni.':'Importa un PGN per iniziare la revisione.';}
function renderMoves(){let html='';const rows=[];for(let i=0;i<moves.length;i++){const m=moves[i],num=new Chess(m.before).moveNumber();let row=rows.at(-1);if(!row||row.num!==num){row={num,w:null,b:null};rows.push(row)}row[m.color]=i}for(const row of rows){html+=`<div class="move-row"><span>${row.num}.</span>`;for(const side of ['w','b']){const i=row[side];if(i===null){html+='<span></span>';continue}html+=`<button class="move-button ${!activeBranch&&index===i+1?'current':''}" data-index="${i+1}" title="${grades[i]?TYPES[grades[i].type].label:'Non analizzata'}"><span>${esc(moves[i].san)}</span>${grades[i]?badge(grades[i].type):'<span style="color:#b0b6a8">·</span>'}</button>`}html+='</div>'}$('moves').innerHTML=html;let grade=grades[index-1],move=moves[index-1];if(!index){$('moveInsight').innerHTML='<span class="eyebrow">POSIZIONE INIZIALE</span><h3>La partita comincia qui.</h3><p>Seleziona una mossa per scoprirne la valutazione.</p>';return}const opening=openingMap[fenKey(positions[index])],before=results[index-1];let best=before?.lines?.[0]?.pv?.[0];let bestSan='';if(best){try{bestSan=new Chess(positions[index-1]).move({from:best.slice(0,2),to:best.slice(2,4),promotion:best[4]||'q'}).san}catch{}}$('moveInsight').innerHTML=grade?`<span class="eyebrow">${new Chess(move.before).moveNumber()}${move.color==='w'?'.':'…'} ${esc(move.san)}</span><h3>${badge(grade.type)} ${TYPES[grade.type].label} <span style="float:right;font-size:15px">${labelScore(results[index])}</span></h3><p>${grade.type==='book'?esc(opening?.name||'Posizione presente nel repertorio delle aperture.'):grade.type==='brilliant'?'Un sacrificio nella linea del motore mantiene una buona posizione.':grade.type==='great'?'Una scelta decisiva: la seconda alternativa è sensibilmente peggiore.':grade.loss>.02?`Perdita stimata: ${(grade.loss*100).toFixed(1)} punti di probabilità. ${bestSan?`Il motore preferiva <b>${esc(bestSan)}</b>.`:''}`:'Mantiene la qualità della posizione secondo il motore.'}${results[index]?.depth?` <span>Profondità ${results[index].depth}.</span>`:''}</p>`:`<span class="eyebrow">MOSSA ${Math.ceil(index/2)}</span><h3>${esc(move.san)}</h3><p>${busy?'Valutazione in corso…':'Questa mossa non è ancora stata analizzata.'}</p>`;}
function updateAccuracy(){for(let side of ['w','b']){let a=grades.filter((g,i)=>g&&moves[i].color===side);$(side==='w'?'whiteAccuracy':'blackAccuracy').textContent=a.length?(a.reduce((s,g)=>s+g.accuracy,0)/a.length).toFixed(1):'—'}renderBoard()}
function renderChart(){const pts=results.map((r,i)=>r?`${(i/Math.max(1,moves.length))*600},${45-40*Math.tanh(r.cp/500)}`:null).filter(Boolean);$('chart').innerHTML=`<line x1="0" y1="45" x2="600" y2="45" stroke="#d7dcd5" stroke-dasharray="4 4"/>${pts.length>1?`<polyline points="${pts.join(' ')}" fill="none" stroke="#77935e" stroke-width="2.2" stroke-linejoin="round"/>`:''}${results[index]?`<circle cx="${index/Math.max(1,moves.length)*600}" cy="${45-40*Math.tanh(results[index].cp/500)}" r="4" fill="#254a37"/>`:''}`}
function render(){renderBoard();renderMoves();renderChart();renderBranches()}
function material(c,side){const val={p:1,n:3,b:3,r:5,q:9,k:0};return c.board().flat().filter(Boolean).reduce((s,p)=>s+(p.color===side?1:-1)*val[p.type],0)}
function isSacrifice(i){const before=results[i],move=moves[i];if(before?.lines?.[0]?.pv?.[0]!==move.from+move.to+(move.promotion||''))return false;const c=new Chess(positions[i]),base=material(c,move.color);try{for(const u of before.lines[0].pv.slice(0,6)){const m=c.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});if(m.color!==move.color&&m.captured&&['n','b','r','q'].includes(m.captured)&&base-material(c,move.color)>=3)return true}}catch{}return false}
async function importGame(){if(busy)return;notify('');const text=$('pgn').value.trim();if(!text){notify('Incolla il testo PGN o carica un file prima di avviare l’analisi.');return}if(text.length>1000000){notify('Il file è troppo grande. Importa una sola partita.');return}try{if((text.match(/\[Event\s/g)||[]).length>1)throw Error('Il testo contiene più partite. Importane una alla volta.');let c=new Chess();c.loadPgn(text,{strict:false});let ms=c.history({verbose:true});if(!ms.length)throw Error('Non ci sono mosse da analizzare nel PGN.');game=c;headers=c.getHeaders();moves=ms;positions=[ms[0].before,...ms.map(m=>m.after)];results=[];grades=[];index=0;branches=[];activeBranch=null;selected=null;liveId++;$('importPanel').hidden=true;$('loadedPanel').hidden=false;$('gameResult').textContent=headers.Result||'*';setTab(false);render();await analyzeGame()}catch(e){notify('Importazione o analisi: '+e.message)}}
async function analyzeGame(){if(busy||!game)return;setTab(false);busy=true;const id=++runId;$('reanalyze').hidden=true;$('cancel').hidden=false;$('progressArea').hidden=false;$('analyze').disabled=true;$('newGame').disabled=true;$('exploreTab').disabled=true;results=[];grades=[];updateAccuracy();render();try{await engine.init();for(let i=0;i<positions.length;i++){if(id!==runId)break;$('progressText').textContent=`Analisi posizione ${i+1} di ${positions.length}…`;$('progressFill').style.width=(i/positions.length*100)+'%';let c=new Chess(positions[0]);for(const m of moves.slice(0,i))c.move({from:m.from,to:m.to,promotion:m.promotion||'q'});results[i]=terminal(c)||await engine.evaluate(positions[i],quality());if(id!==runId)break;if(i>0){const move=moves[i-1];grades[i-1]=classify({before:results[i-1],after:results[i],side:move.color==='w'?1:-1,uci:move.from+move.to+(move.promotion||''),book:bookReady&&!!openingMap[fenKey(positions[i])],sacrifice:isSacrifice(i-1),previousLoss:grades[i-2]?.loss||0})}updateAccuracy();renderMoves();renderChart()}const complete=grades.filter(Boolean).length===moves.length;$('progressText').textContent=complete?`Revisione completata · ${moves.length} mosse analizzate`:`Analisi interrotta · ${grades.filter(Boolean).length}/${moves.length} mosse. Accuracy parziale.`;if(complete)$('progressFill').style.width='100%'}catch(e){notify(e.message);$('progressText').textContent='Analisi incompleta · accuracy parziale'}finally{busy=false;$('analyze').disabled=false;$('newGame').disabled=false;$('exploreTab').disabled=false;$('cancel').hidden=true;$('reanalyze').hidden=false;render()}}
function setTab(explore){if(explore&&!game){notify('Importa prima una partita per esplorare le varianti.');return}if(explore&&busy)return;exploring=explore;$('reviewTab').classList.toggle('active',!explore);$('exploreTab').classList.toggle('active',explore);$('reviewContent').hidden=explore;$('exploreContent').hidden=!explore;if(!explore){activeBranch=null;liveId++;selected=null;render()}else{render();liveAnalyze()}}
function newBranch(analyze=true){if(!game||busy)return;if(activeBranch){const old=activeBranch;activeBranch={id:Date.now()+Math.random(),base:old.base,positions:old.positions.slice(0,branchIndex+1),moves:old.moves.slice(0,branchIndex),results:old.results.slice(0,branchIndex+1)}}else{activeBranch={id:Date.now()+Math.random(),base:index,positions:[positions[index]],moves:[],results:[results[index]]};branchIndex=0}branches.push(activeBranch);render();if(analyze)liveAnalyze()}
function renderBranches(){$('branches').innerHTML='<option value="">Partita originale</option>'+branches.map((b,i)=>`<option value="${b.id}" ${b===activeBranch?'selected':''}>Variante ${i+1} · dopo ${b.base===0?'inizio':`${Math.ceil(b.base/2)}${b.base%2?'.':'…'} ${esc(moves[b.base-1].san)}`}</option>`).join('');$('branchMoves').innerHTML=activeBranch?`<button data-ply="0" class="${branchIndex===0?'current':''}">Inizio</button>`+activeBranch.moves.map((m,i)=>`<button data-ply="${i+1}" class="${branchIndex===i+1?'current':''}">${m.color==='w'?`${new Chess(activeBranch.positions[i]).moveNumber()}.`:''}${esc(m.san)}</button>`).join(''):'<p class="muted">La posizione selezionata nella revisione è il tuo punto di partenza.</p>'}
function pvText(fen,pv){const c=new Chess(fen);const out=[];for(const u of pv.slice(0,10)){try{let n=c.moveNumber(),color=c.turn(),m=c.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});out.push((color==='w'?n+'. ':out.length===0?n+'… ':'')+m.san)}catch{break}}return out.join(' ')}
async function liveAnalyze(){const token=++liveId;liveResult=null;$('playBest').disabled=true;if(!exploring||busy)return;const fen=currentFen(),c=currentChess();$('liveScore').textContent='—';let end=terminal(c);$('pv').textContent=end?end.terminal:'Analisi della posizione…';if(end){$('liveScore').textContent=labelScore(end);return}try{const r=await engine.evaluate(fen,quality());if(token!==liveId||currentFen()!==fen)return;liveResult=r;if(activeBranch)activeBranch.results[branchIndex]=r;$('liveScore').textContent=labelScore(r);$('pv').textContent=pvText(fen,r.pv);$('playBest').disabled=!r.best;renderBoard()}catch(e){if(token===liveId){notify(e.message);$('pv').textContent='Motore non disponibile. Puoi comunque esplorare le mosse legali.'}}}
async function playMove(from,to,promotion){if(!exploring||busy||!game)return;const c=currentChess();const candidates=c.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!candidates.length)return;if(candidates.some(m=>m.promotion)&&!promotion){promotion=await choosePromotion(c.turn());if(!promotion)return}const move=c.move({from,to,promotion:promotion||'q'});if(!move)return;if(!activeBranch||branchIndex<activeBranch.moves.length)newBranch(false);activeBranch.moves.push(move);activeBranch.positions.push(c.fen());branchIndex=activeBranch.moves.length;selected=null;render();liveAnalyze()}
function choosePromotion(color){return new Promise(resolve=>{$('promotionOptions').innerHTML=['q','r','b','n'].map(p=>`<button data-piece="${p}" aria-label="${names[p]}"><img src="pieces/${color}${p.toUpperCase()}.png" alt="${names[p]}"></button>`).join('');$('promotion').showModal();let done=p=>{$('promotion').close();$('promotionOptions').onclick=null;$('promotion').oncancel=null;resolve(p)};$('promotionOptions').onclick=e=>{let b=e.target.closest('[data-piece]');if(b)done(b.dataset.piece)};$('cancelPromotion').onclick=()=>done(null);$('promotion').oncancel=e=>{e.preventDefault();done(null)}})}
function navigate(n){selected=null;if(activeBranch)branchIndex=Math.max(0,Math.min(activeBranch.moves.length,n));else index=Math.max(0,Math.min(moves.length,n));render();if(exploring)liveAnalyze()}
$('board').onclick=e=>{let b=e.target.closest('[data-sq]');if(!b||busy)return;if(!exploring){if(game)notify('Apri “Esplora varianti” per provare mosse sulla scacchiera.');return}let sq=b.dataset.sq,c=currentChess(),p=c.get(sq);if(selected&&c.moves({square:selected,verbose:true}).some(m=>m.to===sq)){playMove(selected,sq);return}selected=p&&p.color===c.turn()?sq:null;renderBoard()};
$('moves').onclick=e=>{let b=e.target.closest('[data-index]');if(b){activeBranch=null;index=Number(b.dataset.index);render()}};
$('branchMoves').onclick=e=>{let b=e.target.closest('[data-ply]');if(b)navigate(Number(b.dataset.ply))};
$('branches').onchange=e=>{activeBranch=branches.find(b=>String(b.id)===e.target.value)||null;branchIndex=activeBranch?.moves.length||0;selected=null;render();liveAnalyze()};
$('original').onclick=()=>{if(activeBranch)index=activeBranch.base;activeBranch=null;selected=null;render();liveAnalyze()};$('addBranch').onclick=()=>newBranch();
$('playBest').onclick=()=>{if(liveResult?.best){const u=liveResult.best;playMove(u.slice(0,2),u.slice(2,4),u[4])}};
$('first').onclick=()=>navigate(0);$('prev').onclick=()=>navigate((activeBranch?branchIndex:index)-1);$('next').onclick=()=>navigate((activeBranch?branchIndex:index)+1);$('last').onclick=()=>navigate(activeBranch?activeBranch.moves.length:moves.length);$('flip').onclick=()=>{flipped=!flipped;renderBoard()};
$('reviewTab').onclick=()=>setTab(false);$('exploreTab').onclick=()=>setTab(true);$('analyze').onclick=importGame;$('reanalyze').onclick=analyzeGame;$('cancel').onclick=()=>{runId++;$('cancel').disabled=true;$('progressText').textContent='Interruzione dopo la posizione corrente…';setTimeout(()=>$('cancel').disabled=false,2500)};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1000000){notify('Carica un file con una sola partita, inferiore a 1 MB.');return}$('pgn').value=await f.text();notify('File caricato. Premi “Analizza partita” per iniziare.');e.target.value=''};
$('newGame').onclick=()=>{$('importPanel').hidden=false;$('loadedPanel').hidden=true;exploring=false;activeBranch=null;liveId++;$('reviewTab').classList.add('active');$('exploreTab').classList.remove('active');notify('');$('pgn').focus();$('importPanel').scrollIntoView({behavior:'smooth',block:'nearest'})};
$('demo').onclick=()=>{$('pgn').value='[Event "Partita dimostrativa"]\n[White "Bianco"]\n[Black "Nero"]\n[Result "1-0"]\n\n1. Nf3 d6 2. e4 Nf6 3. e5 dxe5 4. Nxe5 g6 5. Bc4 Be6 6. Bxe6 fxe6 7. d3 Bg7 8. Qf3 Nd5 9. Qf7# 1-0';importGame()};
$('chart').onclick=e=>{if(!game)return;const rect=$('chart').getBoundingClientRect();activeBranch=null;navigate(Math.round((e.clientX-rect.left)/rect.width*moves.length))};
$('export').onclick=()=>{if(!game){notify('Importa una partita prima di esportare.');return}const c=new Chess(positions[0]);for(const [k,v] of Object.entries(headers))c.setHeader(k,v);const list=activeBranch?[...moves.slice(0,activeBranch.base),...activeBranch.moves]:moves;for(const m of list)c.move({from:m.from,to:m.to,promotion:m.promotion||'q'});if(activeBranch){c.setHeader('Event',(headers.Event||'Partita')+' — Variante');c.setHeader('Result',c.isCheckmate()?(c.turn()==='w'?'0-1':'1-0'):c.isDraw()?'1/2-1/2':'*')}const url=URL.createObjectURL(new Blob([c.pgn()],{type:'application/x-chess-pgn'}));let a=document.createElement('a');a.href=url;a.download=activeBranch?'linea-variante.pgn':'linea-partita.pgn';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
$('methodButton').onclick=()=>$('method').showModal();$('closeMethod').onclick=()=>$('method').close();document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='ArrowLeft'){e.preventDefault();$('prev').click()}if(e.key==='ArrowRight'){e.preventDefault();$('next').click()}});
$('legend').innerHTML=Object.keys(TYPES).map(t=>`<span>${badge(t)} ${TYPES[t].label}</span>`).join('');render();
